"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["1493"],{26240(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>m,frontMatter:()=>p,contentTitle:()=>h,toc:()=>d,assets:()=>c});var a=JSON.parse('{"id":"nhcx/v1/api/biometric/endpoints/biometric-pmjay-sbxhcx-abdmproxy-abha-biometric-faceauth-init","title":"Submit the face auth init","description":"Starts a face authentication on the ABDM proxy host and returns the txnId the rest of the face flow quotes.","source":"@site/docs/nhcx/v1/api/biometric/endpoints/biometric-pmjay-sbxhcx-abdmproxy-abha-biometric-faceauth-init.mdx","sourceDirName":"nhcx/v1/api/biometric/endpoints","slug":"/nhcx/v1/api/biometric/endpoints/biometric-pmjay-sbxhcx-abdmproxy-abha-biometric-faceauth-init","permalink":"/docs/main/docs/nhcx/v1/api/biometric/endpoints/biometric-pmjay-sbxhcx-abdmproxy-abha-biometric-faceauth-init","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Submit the face auth init","sidebar_label":"Submit the face auth init","sidebar_class_name":"api-method api-method--post","description":"Starts a face authentication on the ABDM proxy host and returns the txnId the rest of the face flow quotes.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-biometric.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Get the biometric auth refresh token","permalink":"/docs/main/docs/nhcx/v1/api/biometric/endpoints/biometric-hcx-abha-biometric-auth-refresh-token"},"next":{"title":"Submit the face auth capture PID","permalink":"/docs/main/docs/nhcx/v1/api/biometric/endpoints/biometric-pmjay-sbxhcx-abdmproxy-abha-biometric-capture-pid"}}'),i=n(62540),s=n(43023),o=n(52563),r=JSON.parse('{"id":"biometric_pmjay_sbxhcx_abdmproxy_abha_biometric_faceauth_init","module":"ABHA biometric authentication","moduleId":"biometric","kind":"operation","method":"POST","path":"/pmjay/sbxhcx/abdmproxy/abha/biometric/faceauth/init","server":"https://apisbx.abdm.gov.in","servers":[{"url":"https://apisbx.abdm.gov.in","description":"Sandbox."}],"summary":"Face auth init","title":"Submit the face auth init","description":"Starts a face authentication on the ABDM proxy host and returns the `txnId` the rest of the face flow quotes.\\n\\n### Business purpose\\n\\nFace authentication is the method that works when fingerprint and iris do not. The capture happens on the patient\'s own phone, in the ABHA app, rather than on a hospital device. A case authenticated by fingerprint at admission can be authenticated by face at discharge, because the methods do not have to match across a case.\\n\\n### When to use\\n\\nUse it when fingerprint and iris do not work for the patient. The patient completes the face scan on their own phone, in the ABHA app.\\n\\n### Preconditions\\n\\n- The ABDM session token on `Authorization`, with a fresh `REQUEST-ID` and `TIMESTAMP`.\\n- The request goes to the ABDM proxy host, not the fingerprint host.\\n- The patient has the ABHA app on a phone.\\n\\n### Postconditions\\n\\nReturns a `txnId`. Show `https://phrsbx.abdm.gov.in/face-auth?txnId=<txnId>` as a QR code for the patient to scan with the ABHA app.\\n\\n### Common mistakes\\n\\n- Sending it to the fingerprint host.\\n- Waiting for a callback. There is none, so you poll.\\n- Treating face as optional. All three methods must be built.\\n\\n### Best practices\\n\\n- Keep both biometric base paths in configuration.\\n- Record the `txnId` against the case as soon as it arrives.\\n\\n### Related scenario\\n\\nA patient authenticated by fingerprint at admission cannot be captured on the device at discharge. The desk calls this endpoint, shows the QR code built from the `txnId`, and the patient scans it with the ABHA app. The desk polls `Face auth capture PID` until the capture is complete, then calls `Face auth verify`.\\n\\n### Specification\\n\\nChapter [Biometric authentication](/docs/nhcx/v1/roles/provider/biometric-authentication) of the NHCX integration specification.","gateway":"nhcx","security":[],"headers":[{"name":"REQUEST-ID","required":true,"description":"`REQUEST-ID` is a fresh UUID that you generate for every call. Sending the same one twice is the mistake to avoid; generate it, do not copy it from an example.","example":"<uuid>","type":"string"},{"name":"TIMESTAMP","required":true,"description":"`TIMESTAMP` is the current time in UTC, ISO 8601 with milliseconds and a trailing `Z`, as in `2026-09-04T06:15:51.975Z`. A clock that has drifted will be refused, so take the time from the system rather than constructing it by hand. How to produce it in each language is at the end of this chapter.","example":"<iso timestamp>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"scope","type":"string[]","required":false,"description":"","encrypted":false}],"requestExample":{"scope":["abha-enrol","face-auth"]},"responses":[{"status":"200","description":"Returns a `txnId`.","synthesised":false,"fields":[]}],"curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/abdmproxy/abha/biometric/faceauth/init \\\\\\n  --header \'REQUEST-ID: <uuid>\' \\\\\\n  --header \'TIMESTAMP: <iso timestamp>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"scope\\": [\\n    \\"abha-enrol\\",\\n    \\"face-auth\\"\\n  ]\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/abdmproxy/abha/biometric/faceauth/init \\\\\\n  --header \'REQUEST-ID: <uuid>\' \\\\\\n  --header \'TIMESTAMP: <iso timestamp>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"scope\\": [\\n    \\"abha-enrol\\",\\n    \\"face-auth\\"\\n  ]\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/abdmproxy/abha/biometric/faceauth/init\\",\\n    headers={\\n        \\"REQUEST-ID\\": \\"<uuid>\\",\\n        \\"TIMESTAMP\\": \\"<iso timestamp>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"scope\\": [\\n            \\"abha-enrol\\",\\n            \\"face-auth\\"\\n        ]\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node.js","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/abdmproxy/abha/biometric/faceauth/init\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"REQUEST-ID\\": \\"<uuid>\\",\\n    \\"TIMESTAMP\\": \\"<iso timestamp>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"scope\\": [\\n      \\"abha-enrol\\",\\n      \\"face-auth\\"\\n    ]\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"},{"id":"java","label":"Java","language":"java","code":"import java.net.URI;\\nimport java.net.http.HttpClient;\\nimport java.net.http.HttpRequest;\\nimport java.net.http.HttpResponse;\\n\\nHttpClient client = HttpClient.newHttpClient();\\nHttpRequest request = HttpRequest.newBuilder()\\n    .uri(URI.create(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/abdmproxy/abha/biometric/faceauth/init\\"))\\n    .header(\\"REQUEST-ID\\", \\"<uuid>\\")\\n    .header(\\"TIMESTAMP\\", \\"<iso timestamp>\\")\\n    .header(\\"Content-Type\\", \\"application/json\\")\\n    .method(\\"POST\\", HttpRequest.BodyPublishers.ofString(\\"\\"\\"\\n        {\\n            \\"scope\\": [\\n                \\"abha-enrol\\",\\n                \\"face-auth\\"\\n            ]\\n        }\\n        \\"\\"\\"))\\n    .build();\\n\\nHttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());\\nSystem.out.println(response.statusCode() + \\" \\" + response.body());"},{"id":"php","label":"PHP","language":"php","code":"<?php\\n\\n$ch = curl_init(\'https://apisbx.abdm.gov.in/pmjay/sbxhcx/abdmproxy/abha/biometric/faceauth/init\');\\ncurl_setopt_array($ch, [\\n    CURLOPT_CUSTOMREQUEST => \'POST\',\\n    CURLOPT_RETURNTRANSFER => true,\\n    CURLOPT_HTTPHEADER => [\\n        \'REQUEST-ID: <uuid>\',\\n        \'TIMESTAMP: <iso timestamp>\',\\n        \'Content-Type: application/json\',\\n    ],\\n    CURLOPT_POSTFIELDS => <<<\'JSON\'\\n    {\\n        \\"scope\\": [\\n            \\"abha-enrol\\",\\n            \\"face-auth\\"\\n        ]\\n    }\\n    JSON,\\n]);\\n\\n$response = curl_exec($ch);\\necho curl_getinfo($ch, CURLINFO_HTTP_CODE), \' \', $response, PHP_EOL;"},{"id":"go","label":"Go","language":"go","code":"package main\\n\\nimport (\\n\\t\\"fmt\\"\\n\\t\\"io\\"\\n\\t\\"net/http\\"\\n\\t\\"strings\\"\\n)\\n\\nfunc main() {\\n\\tbody := strings.NewReader(`{\\n  \\"scope\\": [\\n    \\"abha-enrol\\",\\n    \\"face-auth\\"\\n  ]\\n}`)\\n\\treq, err := http.NewRequest(\\"POST\\", \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/abdmproxy/abha/biometric/faceauth/init\\", body)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\treq.Header.Set(\\"REQUEST-ID\\", \\"<uuid>\\")\\n\\treq.Header.Set(\\"TIMESTAMP\\", \\"<iso timestamp>\\")\\n\\treq.Header.Set(\\"Content-Type\\", \\"application/json\\")\\n\\n\\tresp, err := http.DefaultClient.Do(req)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\tdefer resp.Body.Close()\\n\\tout, _ := io.ReadAll(resp.Body)\\n\\tfmt.Println(resp.StatusCode, string(out))\\n}"},{"id":"csharp","label":"C#","language":"csharp","code":"using var client = new HttpClient();\\nvar request = new HttpRequestMessage(new HttpMethod(\\"POST\\"), \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/abdmproxy/abha/biometric/faceauth/init\\");\\nrequest.Headers.TryAddWithoutValidation(\\"REQUEST-ID\\", \\"<uuid>\\");\\nrequest.Headers.TryAddWithoutValidation(\\"TIMESTAMP\\", \\"<iso timestamp>\\");\\nrequest.Content = new StringContent(\\"\\"\\"\\n    {\\n        \\"scope\\": [\\n            \\"abha-enrol\\",\\n            \\"face-auth\\"\\n        ]\\n    }\\n    \\"\\"\\", System.Text.Encoding.UTF8, \\"application/json\\");\\n\\nvar response = await client.SendAsync(request);\\nConsole.WriteLine($\\"{(int)response.StatusCode} {await response.Content.ReadAsStringAsync()}\\");"},{"id":"ruby","label":"Ruby","language":"ruby","code":"require \'net/http\'\\n\\nuri = URI(\'https://apisbx.abdm.gov.in/pmjay/sbxhcx/abdmproxy/abha/biometric/faceauth/init\')\\nrequest = Net::HTTP::Post.new(uri)\\nrequest[\'REQUEST-ID\'] = \'<uuid>\'\\nrequest[\'TIMESTAMP\'] = \'<iso timestamp>\'\\nrequest[\'Content-Type\'] = \'application/json\'\\nrequest.body = <<~\'JSON\'\\n  {\\n    \\"scope\\": [\\n      \\"abha-enrol\\",\\n      \\"face-auth\\"\\n    ]\\n  }\\nJSON\\n\\nresponse = Net::HTTP.start(uri.hostname, uri.port, use_ssl: uri.scheme == \'https\') do |http|\\n  http.request(request)\\nend\\nputs response.code, response.body"}]}');let p={title:"Submit the face auth init",sidebar_label:"Submit the face auth init",sidebar_class_name:"api-method api-method--post",description:"Starts a face authentication on the ABDM proxy host and returns the txnId the rest of the face flow quotes.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-biometric.yaml",generated:!0},h,c={},d=[];function u(e){return(0,i.jsx)(o.Ay,{operation:r})}function m(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(u,{...e})}):u(e)}}}]);